// device_status.go
// Simple Go program that reads a JSON list of network devices from a file
// and prints a table showing the device name, IP address and status.
//
// Expected JSON format (array of objects):
// [
//   {"name": "router-01", "ip": "10.0.0.1", "status": "up"},
//   {"name": "switch-02", "ip": "10.0.0.2", "status": "down"}
// ]

package main

import (
    "encoding/json"
    "fmt"
    "log"
    "os"
    "text/tabwriter"
)

type Device struct {
    Name   string `json:"name"`
    IP     string `json:"ip"`
    Status string `json:"status"`
}

func main() {
    if len(os.Args) < 2 {
        fmt.Println("Usage: device_status <json-file>")
        os.Exit(1)
    }
    filePath := os.Args[1]
    data, err := os.ReadFile(filePath)
    if err != nil {
        log.Fatalf("Failed to read file: %v", err)
    }

    var devices []Device
    if err := json.Unmarshal(data, &devices); err != nil {
        log.Fatalf("Failed to parse JSON: %v", err)
    }

    // Use tabwriter for aligned columns
    w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
    fmt.Fprintln(w, "NAME\tIP ADDRESS\tSTATUS")
    fmt.Fprintln(w, "----\t----------\t------")
    for _, d := range devices {
        fmt.Fprintf(w, "%s\t%s\t%s\n", d.Name, d.IP, d.Status)
    }
    w.Flush()
}

