// loadDevices reads a JSON file and unmarshals it into a slice of Device.
// It accepts either an array []Device or a single object {}.
func loadDevices(path string) ([]Device, error) {
	if path == "" {
		return nil, fmt.Errorf("file path cannot be empty")
	}
	data, err := os.ReadFile(path)
