	}
	var devs []Device
	if err := json.Unmarshal(data, &devs); err != nil {
		// Try single‑object fallback
		var single Device
		if err2 := json.Unmarshal(data, &single); err2 == nil {
			devs = []Device{single}
		} else {
			return nil, err // original array error
		}
	}
	return devs, nil
}

