// Empty filter returns the input unchanged.
// Comparison is case‑insensitive.
func filterByStatus(devs []Device, filter string) []Device {
	if filter == "" {
		return devs
	}
	var out []Device
	for _, d := range devs {
		if strings.EqualFold(d.Status, filter) {
			out = append(out, d)
		}
	}
	return out
}

// printTable writes a simple tab‑aligned table to stdout.
func printTable(devs []Device) {
	w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(w, "NAME\tIP ADDRESS\tSTATUS")
	fmt.Fprintln(w, "----\t----------\t------")
	for _, d := range devs {
		fmt.Fprintf(w, "%s\t%s\t%s\n", d.Name, d.IP, d.Status)
	}
	w.Flush()
}

func main() {
	filePath := flag.String("file", "devices.json", "Path to the JSON file containing the device list")
	statusFilter := flag.String("status", "", "If set, only devices with this status are displayed (e.g., up, down)")
	flag.Parse()

	devs, err := loadDevices(*filePath)
	if err != nil {
		log.Fatalf("Failed to read devices from %s: %v", *filePath, err)
	}

	devs = filterByStatus(devs, *statusFilter)

	if len(devs) == 0 {
		fmt.Println("No devices to display.")
		return
	}

	fmt.Printf("Showing %d device(s)\n", len(devs))
	printTable(devs)
