I’ve added a **Go test suite** that verifies the core functions of the program.

**File:** `device_status_test.go` (attached)

```go
package main

import (
	"io/ioutil"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

// ---------------------------------------------------------------------
// Test loadDevices – array JSON
// ---------------------------------------------------------------------
func TestLoadDevices_Array(t *testing.T) {
	jsonData := `[
		{"name":"router-01","ip":"10.0.0.1","status":"up"},
		{"name":"switch-02","ip":"10.0.0.2","status":"down"}
	]`

	tmpFile := writeTempFile(t, jsonData)
	defer os.Remove(tmpFile)

	devs, err := loadDevices(tmpFile)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(devs) != 2 {
		t.Fatalf("expected 2 devices, got %d", len(devs))
	}
	if devs[0].Name != "router-01" || devs[1].Status != "down" {
		t.Fatalf("unexpected device data: %+v", devs)
	}
}

// ---------------------------------------------------------------------
// Test loadDevices – single object JSON
// ---------------------------------------------------------------------
func TestLoadDevices_SingleObject(t *testing.T) {
	jsonData := `{"name":"firewall-01","ip":"10.0.0.3","status":"up"}`

	tmpFile := writeTempFile(t, jsonData)
	defer os.Remove(tmpFile)

	devs, err := loadDevices(tmpFile)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(devs) != 1 {
		t.Fatalf("expected 1 device, got %d", len(devs))
	}
	if devs[0].Name != "firewall-01" {
		t.Fatalf("unexpected device: %+v", devs[0])
	}
}

// ---------------------------------------------------------------------
// Test filterByStatus – exact match & case‑insensitive
// ---------------------------------------------------------------------
func TestFilterByStatus(t *testing.T) {
	devs := []Device{
		{Name: "router-01", IP: "10.0.0.1", Status: "Up"},
		{Name: "switch-01", IP: "10.0.0.2", Status: "down"},
		{Name: "firewall-01", IP: "10.0.0.3", Status: "UP"},
	}

	// No filter – should return all
	if got := filterByStatus(devs, ""); !reflect.DeepEqual(got, devs) {
		t.Fatalf("filter without criteria returned unexpected slice")
	}

	// Filter “up” – case‑insensitive, should match 2 devices
	expected := []Device{devs[0], devs[2]}
	if got := filterByStatus(devs, "up"); !reflect.DeepEqual(got, expected) {
		t.Fatalf("filterByStatus(up) = %+v, want %+v", got, expected)
	}

	// Filter “DOWN” – should match 1 device
	expected = []Device{devs[1]}
	if got := filterByStatus(devs, "DOWN"); !reflect.DeepEqual(got, expected) {
		t.Fatalf("filterByStatus(DOWN) = %+v, want %+v", got, expected)
	}
}

// ---------------------------------------------------------------------
// Helper – create a temporary file with the given contents
// ---------------------------------------------------------------------
func writeTempFile(t *testing.T, data string) string {
	t.Helper()
	dir := t.TempDir()
	tmpPath := filepath.Join(dir, "tmp.json")
	if err := ioutil.WriteFile(tmpPath, []byte(data), 0o600); err != nil {
		t.Fatalf("cannot write temp file: %v", err)
	}
	return tmpPath
}
```

